def calculate_edit_distance(first_string, second_string, threshold=None):
    if not first_string:
        return len(second_string)
    if not second_string:
        return len(first_string)
    edit_distance_table = [[0 for _ in range(len(second_string) + 1)] for _ in range(len(first_string) + 1)]

    for i in range(len(first_string) + 1):
        for j in range(len(second_string) + 1):
            if i == 0:
                edit_distance_table[i][j] = j  # Insert all characters of second string
            elif j == 0:
                edit_distance_table[i][j] = i  # Delete all characters of first string
            elif first_string[i - 1] == second_string[j - 1]:
                edit_distance_table[i][j] = edit_distance_table[i - 1][j - 1]  # Match, no edit distance
            else:
                edit_distance_table[i][j] = 1 + min(
                    edit_distance_table[i][j - 1],  # Insertion
                    edit_distance_table[i - 1][j],  # Deletion
                    edit_distance_table[i - 1][j - 1]  # Substitution
                )

    edit_distance = edit_distance_table[-1][-1]

    if threshold and edit_distance > threshold:
        raise Exception(f"Edit distance {edit_distance} exceeds the specified threshold {threshold}")

    return edit_distance
```

This implementation calculates the edit distance between two strings using dynamic programming, where the edit distance table is filled iteratively. The function takes two input strings and an optional `threshold` parameter, and raises an exception if the edit distance exceeds the threshold.

