import torch

def calculate_overlap_area(rect1, rect2):
    if not isinstance(rect1, torch.Tensor) or not isinstance(rect2, torch.Tensor):
        raise ValueError("Input must be tensors")

    if rect1.shape != (4,) or rect2.shape != (4,):
        raise ValueError("Input must be tensors with shape (4,)")
    if rect1[2] <= 0 or rect1[3] <= 0 or rect2[2] <= 0 or rect2[3] <= 0:
        raise ValueError("Height and width must be greater than zero")
    if rect1[0] + rect1[2] <= rect2[0] or rect1[0] >= rect2[0] + rect2[2] or rect1[1] + rect1[3] <= rect2[1] or rect1[1] >= rect2[1] + rect2[3]:
        return 0
    x1 = max(rect1[0], rect2[0])
    y1 = max(rect1[1], rect2[1])
    x2 = min(rect1[0] + rect1[2], rect2[0] + rect2[2])
    y2 = min(rect1[1] + rect1[3], rect2[1] + rect2[3])

    return (x2 - x1) * (y2 - y1)

