def string_to_float(s):
    s = s.strip() # Remove leading and trailing whitespace
    decimal_index = -1 # Initialize index of decimal point
    for i in range(len(s)):
        if s[i] == '.':
            decimal_index = i # Update index of decimal point
            break

    # Convert the string to a float
    float_value = 0.0
    for i in range(len(s)):
        if i != decimal_index:
            digit = ord(s[i]) - ord('0') # Convert character to integer
            float_value = float_value * 10 + digit

    # Adjust the float value based on the position of decimal point
