def merge_dicts_by_key(main_data, secondary_data, key):
    try:
        secondary_dict = {d[key]: d for d in secondary_data}
        result = []

        for item in main_data:
            secondary_item = secondary_dict.get(item.get(key))
            if secondary_item is None:
                raise ValueError("Key-value pairs in the secondary list do not match those in the main list")
            merged = {**item, **secondary_item}
            if merged not in result: # to ensure distinct dictionaries in output
                result.append(merged)
        return result
    except KeyError:
        return "A key does not exist in one of the lists"

