def organize_numbers(input_list):
    output_dict = {}
    for num in input_list:
        first_digit = str(num)[0]
        if first_digit in output_dict:
            output_dict[first_digit].append(num)
        else:
            output_dict[first_digit] = [num]

    for key, value in output_dict.items():
        value.sort()
        output_dict[key] = ' '.join(str(x) for x in value)

    for i in range(10):
        digit = str(i)
        if digit not in output_dict:
            output_dict[digit] = ''

    for key in sorted(output_dict.keys()):
