    total_confirmed = 0
    total_deaths = 0
    total_recovered = 0
    if country in parsed_data:
        for province_state in parsed_data[country]:
            total_confirmed += parsed_data[country][province_state]['confirmed']
            total_deaths += parsed_data[country][province_state]['deaths']
            total_recovered += parsed_data[country][province_state]['recovered']
    return total_confirmed, total_deaths, total_recovered

def total_cases_by_province(parsed_data, country, province):
    if country in parsed_data and province in parsed_data[country]:
        return parsed_data[country][province]['confirmed'], parsed_data[country][province]['deaths'], parsed_data[country][province]['recovered']
    else:
        return 0, 0, 0

