def remove_duplicates(lst):
    # Helper function to check if two elements are equal
    def are_equal(a, b):
        if isinstance(a, str) and isinstance(b, str):
            return a.lower() == b.lower()
        elif isinstance(a, type(None)) and isinstance(b, type(None)):
            return True
        elif isinstance(a, list) and isinstance(b, list):
            return are_equal_lists(a, b)
        elif isinstance(a, object) and isinstance(b, object):
            return getattr(a, 'attribute') == getattr(b, 'attribute')
        else:
            return a == b

    # Helper function to check if two lists are equal
    def are_equal_lists(a, b):
        if len(a) != len(b):
            return False
        for i in range(len(a)):
            if not are_equal(a[i], b[i]):
                return False
        return True

    # Main function logic
    result = []
    for i in range(len(lst)):
        is_duplicate = False
        for j in range(i+1, len(lst)):
