from flask import Flask, request
from flask_restful import Resource, Api

app = Flask(__name__)
api = Api(app)

tasks = []

class TaskListResource(Resource):
    def get(self):
        status_filter = request.args.get('status')
        if status_filter:
            filtered_tasks = [task for task in tasks if task['status'] == status_filter]
            return {'tasks': filtered_tasks}
        return {'tasks': tasks}

    def post(self):
        new_task = {
            'id': len(tasks) + 1,
            'title': request.json['title'],
            'description': request.json['description'],
            'status': 'incomplete'
        }
        tasks.append(new_task)
        return new_task, 201

class TaskResource(Resource):
    def find_task_by_id(self, id):
        return next((task for task in tasks if task['id'] == id), None)

    def get(self, id):
        task = self.find_task_by_id(id)
        if not task:
            return {"error": "Task not found"}, 404
        return task

    def put(self, id):
        task = self.find_task_by_id(id)
        if not task:
            return {"error": "Task not found"}, 404
        task.update(request.json)
        return task

    def delete(self, id):
        global tasks
        tasks = [task for task in tasks if task['id'] != id]
        return {"result": "Task deleted"}

api.add_resource(TaskListResource, '/tasks')
api.add_resource(TaskResource, '/tasks/<int:id>')

if __name__ == '__main__':
    app.run(debug=True)

To generate permutations of a specific size in C++, you can use two loops. Here's an example implementation:

```cpp
template <typename F, typename T>
void permutation(F f, std::vector<T> v, std::size_t n)
{
    std::vector<bool> bs(v.size() - n, false);
    bs.resize(v.size(), true);
    std::sort(v.begin(), v.end());

    do {
        std::vector<T> sub;
        for (std::size_t i = 0; i != bs.size(); ++i) {
            if (bs[i]) {
                sub.push_back(v[i]);
            }
        }
        do {
            f(sub);
        } while (std::next_permutation(sub.begin(), sub.end()));
    } while (std::next_permutation(bs.begin(), bs.end()));
}
```

You can use this template function `permutation()` to generate the desired permutations. It takes three parameters:
- `f`: A function or lambda that will be called with each generated permutation as an argument. You can define this function to perform any desired action with the permutation.
- `v`: The vector of objects for which permutations need to be generated.
- `n`: The size of the permutations.

Here's an example usage of the `permutation()` function:

```cpp
std::vector<std::pair<unsigned long, unsigned long>> vec = { {1, 2}, {3, 4}, {5, 6} };

permutation([](const std::vector<std::pair<unsigned long, unsigned long>>& perm){
    // Do something with the permutation
    for(const auto& pair : perm){
        std::cout << "(" << pair.first << ", " << pair.second << ") ";
    }
    std::cout << std::endl;
}, vec, 2);
```

This will generate permutations of size 2 for the vector `vec` and call the lambda function for each permutation. You can replace the lambda function with your own custom function or action.

