```
import java.util.ArrayList;
import java.util.Arrays;
public class FriendsPowers {
    public static void main(String[] args) {
        int x = 100; // the number needed to take down the forcefield
        String[] powers = {"A", "B", "C", "D", "E"}; // the friends' powers
        ArrayList<String[]> permutations = new ArrayList<String[]>();
        generatePermutations(powers, permutations, 0);
        for (String[] permutation : permutations) {
            int result = calculateResult(permutation, x);
            if (result == x) {
                System.out.println(Arrays.toString(permutation));
                break;
            }
        }
    }

    public static void generatePermutations(String[] powers, ArrayList<String[]> permutations, int index) {
        if (index == powers.length) {
            permutations.add(powers.clone());
        } else {
            for (int i = index; i < powers.length; i++) {
                swap(powers, index, i);
                generatePermutations(powers, permutations, index + 1);
                swap(powers, index, i);
            }
        }
    }

    public static void swap(String[] powers, int i, int j) {
        String temp = powers[i];
        powers[i] = powers[j];
        powers[j] = temp;
    }

    public static int calculateResult(String[] powers, int x) {
        int result = x;
        for (String power : powers) {
            switch (power) {
                case "A":
                    result *= 3;
                    break;
                case "B":
                    result /= 2;
                    break;
                case "C":
                    result += 10;
                    break;
                case "D":
                    result -= 5;
                    break;
                case "E":
                    result *= result;
                    break;
            }
        }
        return result;
    }
}
```
