using System;
using System.Collections.Generic;

public class MyCalendar {
    private List<int> calendar;

    public MyCalendar() {
        calendar = new List<int>();
    }

    public bool Book(int start, int end) {
        int i = 0;
        while (i < calendar.Count) {
            if (start < calendar[i + 1] && end > calendar[i]) {
                return false;
            }
            i += 2;
        }
        calendar.Insert(i, end);
        calendar.Insert(i, start);
        return true;
    }
