struct pro {
  int sSmall, sLarge, tSmall, tLarge;
  double probFail;
  void read() {
    scanf("%d%d%d%d%lf", &sSmall, &sLarge, &tSmall, &tLarge, &probFail);
  }
  double calc() const { return probFail / (1 - probFail) * tLarge; }
