def verify_checksum(ean):
    total = 0
    for i in range(12):
        if i % 2 == 0:
            total += int(ean[i])
        else:
            total += int(ean[i]) * 3
    check_digit = (10 - (total % 10)) % 10
    return check_digit == int(ean[-1])

ean = "9780201310054"
