import ast
import os

class ReadFileInlineDocumentationVisitor(ast.NodeVisitor):
    def __init__(self, filename):
        self.filename = filename
        self.line_num = 1
        self.inline_documentation = []

    def visit_FunctionDef(self, node):
        if len(node.body) > 0 and isinstance(node.body[0], ast.Expr) and isinstance(node.body[0].value, ast.Str):
            self.inline_documentation.append(node.body[0].value.s)
        self.generic_visit(node)

    def visit_ClassDef(self, node):
        if len(node.body) > 0 and isinstance(node.body[0], ast.Expr) and isinstance(node.body[0].value, ast.Str):
            self.inline_documentation.append(node.body[0].value.s)
        self.generic_visit(node)

    def visit_Expr(self, node):
        if isinstance(node.value, ast.Str):
            self.inline_documentation.append(node.value.s)
        self.generic_visit(node)

    def generic_visit(self, node):
        if hasattr(node, 'lineno'):
            self.line_num = node.lineno
        super().generic_visit(node)

def read_file_inline_documentation(filename):
    with open(filename) as file:
        source = file.read()
    tree = ast.parse(source, filename)
    visitor = ReadFileInlineDocumentationVisitor(filename)
    visitor.visit(tree)
    return [doc[:100] for doc in visitor.inline_documentation]
```

