        visited[N - 1][N - 1] = 1;
        vector<int> path = {chessboard[N - 1][N - 1]};
        dfs(N - 1, N - 1, k - 1, path, chessboard, chessboard[N - 1][N - 1]);
        return max_path;
    }
};
