def hex_to_dec(hex_string):
    if not is_valid(hex_string):
        raise ValueError("Invalid hexadecimal string")
    decimal, power_bottom = 0, 0
    hex_map = {str(i): i for i in range(10)}
    hex_map.update({"A": 10, "B": 11, "C": 12, "D": 13, "E": 14, "F": 15})
    for digit in reversed(hex_string.upper()):
        decimal += hex_map[digit] * pow(16, power_bottom)
        power_bottom += 1
    return decimal

def is_valid(hex_string):
